package org.securemail.relay;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.CountDownLatch;
/** Explicit opt-in Identity6 Relay operator CLI; never enables the gate on an existing RelayMain. */
public final class RelayMain600 {
 private RelayMain600(){}
 public static void main(String[] args)throws Exception{
  if(args.length<1)throw new IllegalArgumentException("init | serve | inspect --home DIR");Map<String,String> options=new LinkedHashMap<>();for(int i=1;i<args.length;i+=2){if(i+1>=args.length||!args[i].startsWith("--")||options.put(args[i],args[i+1])!=null)throw new IllegalArgumentException("Параметры Relay6");}
  if(!Set.of("--home","--config","--identity-public","--identity-fingerprint","--identity-port").containsAll(options.keySet()))throw new IllegalArgumentException("Неизвестный параметр Relay6");Path home=Path.of(required(options,"--home")).toAbsolutePath().normalize();
  switch(args[0]){
   case "init"->initialize(home,Path.of(required(options,"--config")),Path.of(required(options,"--identity-public")),required(options,"--identity-fingerprint"),Integer.parseInt(required(options,"--identity-port")),System.out);
   case "inspect"->{Properties p=readConfig(home);System.out.println("Relay6 identity pin: "+p.getProperty("identityFingerprint")+"; service fingerprint: "+IdentityProtocol.id(publicFile(home.resolve("service-public.x509")))+"; productionDeployed=false");}
   case "serve"->{try(Running running=start(home)){CountDownLatch stop=new CountDownLatch(1);Thread hook=new Thread(stop::countDown,"relay6-shutdown");Runtime.getRuntime().addShutdownHook(hook);try{System.out.println("Relay6 слушает 127.0.0.1:"+running.port()+"; требуется отдельный onion service и allowlist Relay public key в Identity.");stop.await();}finally{Runtime.getRuntime().removeShutdownHook(hook);}}}
   default->throw new IllegalArgumentException("init | serve | inspect");
  }
 }
 public static void initialize(Path directory,Path config,Path identityPublic,String fingerprint,int identityPort,PrintStream output)throws Exception{
  Path home=directory.toAbsolutePath().normalize();if(identityPort<1||identityPort>65535||Files.isSymbolicLink(home)||Files.exists(home.resolve("INITIALIZED600")))throw new IOException("Relay6 уже подготовлен либо путь недопустим");
  byte[] pin=publicFile(identityPublic);if(!IdentityProtocol.id(pin).equals(IdentityProtocol.idValue(fingerprint)))throw new IOException("Отпечаток Identity не совпадает");Path source=config.toAbsolutePath().normalize();if(Files.isSymbolicLink(source)||!Files.isRegularFile(source,LinkOption.NOFOLLOW_LINKS)||Files.size(source)>16384)throw new IOException("Конфигурация Relay недоступна");RelayConfig validated=RelayConfig.load(source);Files.createDirectories(home);if(!home.toRealPath().equals(home))throw new IOException("Символический каталог Relay6");privateMode(home,true);
  if(Files.exists(home.resolve("service.key")))throw new IOException("Ключ Relay6 уже существует; автоматическая замена запрещена");KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();writePrivate(home.resolve("service.key"),encode(pair));Files.write(home.resolve("service-public.x509"),pair.getPublic().getEncoded(),StandardOpenOption.CREATE_NEW);Files.writeString(home.resolve("service-public.txt"),IdentityProtocol.b64(pair.getPublic().getEncoded())+"\n",StandardOpenOption.CREATE_NEW);Files.write(home.resolve("identity-public.x509"),pin,StandardOpenOption.CREATE_NEW);
  Properties p=new Properties();p.setProperty("relayConfig",source.toString());p.setProperty("identityFingerprint",fingerprint);p.setProperty("identityPort",Integer.toString(identityPort));try(OutputStream out=Files.newOutputStream(home.resolve("relay6.properties"),StandardOpenOption.CREATE_NEW)){p.store(out,"AEGIS Relay6 explicit opt-in; no production activation");}privateMode(home.resolve("relay6.properties"),false);Files.writeString(home.resolve("INITIALIZED600"),"AEGIS-RELAY6/v1\n",StandardOpenOption.CREATE_NEW);
  output.println("Relay6 service fingerprint: "+IdentityProtocol.id(pair.getPublic().getEncoded()));output.println("Разрешите только публичный service-public.txt через aegis-admin service relay allow --fingerprint SHA256. Existing RelayMain не изменён. База: "+validated.databasePath());
 }
 public static Running start(Path directory)throws Exception{
  Path home=directory.toAbsolutePath().normalize();Properties p=readConfig(home);byte[] identity=publicFile(home.resolve("identity-public.x509"));if(!IdentityProtocol.id(identity).equals(p.getProperty("identityFingerprint")))throw new IOException("Отпечаток Identity изменён");KeyPair pair=decode(readPrivate(home.resolve("service.key")));if(!MessageDigest.isEqual(pair.getPublic().getEncoded(),publicFile(home.resolve("service-public.x509"))))throw new IOException("Открытый ключ Relay изменён");RelayConfig config=RelayConfig.load(Path.of(p.getProperty("relayConfig")));RelayStore store=new RelayStore(config,Clock.systemUTC());PinnedRelaySessionGate600 gate=null;RelayServer server=null;try{gate=new PinnedRelaySessionGate600(Integer.parseInt(p.getProperty("identityPort")),identity,pair);server=new RelayServer(config,store,Clock.systemUTC(),gate);server.start();return new Running(store,server);}catch(Exception failure){if(server!=null)server.close();else if(gate!=null)gate.close();store.close();throw failure;}
 }
 public static final class Running implements AutoCloseable{private final RelayStore store;private final RelayServer server;Running(RelayStore store,RelayServer server){this.store=store;this.server=server;}public int port(){return server.port();}@Override public void close()throws Exception{try{server.close();}finally{store.close();}}}
 private static Properties readConfig(Path home)throws Exception{if(Files.isSymbolicLink(home)||!home.toRealPath().equals(home)||!Files.readString(home.resolve("INITIALIZED600")).equals("AEGIS-RELAY6/v1\n"))throw new IOException("Relay6 не подготовлен");Properties p=new Properties();byte[] bytes=readPrivate(home.resolve("relay6.properties"));try(InputStream input=new ByteArrayInputStream(bytes)){p.load(input);}finally{Arrays.fill(bytes,(byte)0);}if(!p.keySet().equals(Set.of("relayConfig","identityFingerprint","identityPort")))throw new IOException("Конфигурация Relay6");return p;}
 private static String required(Map<String,String> options,String key){String value=options.get(key);if(value==null)throw new IllegalArgumentException("Не указан "+key);return value;}
 private static byte[] publicFile(Path file)throws IOException{if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>256)throw new IOException("Публичный ключ недоступен");byte[] bytes=Files.readAllBytes(file);try{return IdentityProtocol.publicKey(bytes.length==44?bytes:IdentityProtocol.unb64(new String(bytes,java.nio.charset.StandardCharsets.US_ASCII).trim(),44)).getEncoded();}catch(IllegalArgumentException invalid){throw new IOException("Публичный ключ некорректен");}}
 private static byte[] readPrivate(Path file)throws IOException{if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>16384)throw new IOException("Файл Relay6 недоступен");try{if(!Files.getPosixFilePermissions(file).equals(PosixFilePermissions.fromString("rw-------")))throw new IOException("Файл Relay6 требует 0600");}catch(UnsupportedOperationException ignored){}return Files.readAllBytes(file);}
 private static void privateMode(Path file,boolean directory)throws IOException{try{Files.setPosixFilePermissions(file,PosixFilePermissions.fromString(directory?"rwx------":"rw-------"));}catch(UnsupportedOperationException ignored){}}
 private static void writePrivate(Path file,byte[] bytes)throws IOException{try{try{Files.createFile(file,PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------")));}catch(UnsupportedOperationException ignored){Files.createFile(file);}Files.write(file,bytes,StandardOpenOption.WRITE);}finally{Arrays.fill(bytes,(byte)0);}}
 private static byte[] encode(KeyPair pair)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeUTF("AEGIS-RELAY6-SERVICE/v1");out.write(pair.getPublic().getEncoded());byte[] secret=pair.getPrivate().getEncoded();try{out.writeInt(secret.length);out.write(secret);}finally{Arrays.fill(secret,(byte)0);}}return bytes.toByteArray();}
 private static KeyPair decode(byte[] encoded)throws Exception{try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(encoded))){if(!in.readUTF().equals("AEGIS-RELAY6-SERVICE/v1"))throw new IOException("Формат ключа Relay6");byte[] pub=in.readNBytes(44);int n=in.readInt();if(n<32||n>128)throw new IOException("Длина ключа");byte[] privateBytes=in.readNBytes(n);try{if(privateBytes.length!=n||in.read()!=-1)throw new IOException("Ключ Relay6 повреждён");return new KeyPair(IdentityProtocol.publicKey(pub),KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(privateBytes)));}finally{Arrays.fill(privateBytes,(byte)0);}}finally{Arrays.fill(encoded,(byte)0);}}
}
